// Shared person identity is opaque and stable. Training receives personId, never these facet ids.
export const platformPersons = pgTable('platform_persons', { id: uuid('id').defaultRandom().primaryKey(), status: text('status').notNull().default('active'), createdBy: text('created_by').notNull(), createdAt: timestamp('created_at',{withTimezone:true}).notNull().defaultNow(), updatedAt: timestamp('updated_at',{withTimezone:true}).notNull().defaultNow() }, t => [check('platform_persons_status_check',sql`${t.status} IN ('active','revoked')`),check('platform_persons_actor_check',sql`char_length(${t.createdBy}) BETWEEN 1 AND 120`)]);
export const platformPersonClients = pgTable('platform_person_clients', { personId: uuid('person_id').notNull().references(()=>platformPersons.id,{onDelete:'restrict'}), clientId: uuid('client_id').notNull().references(()=>clients.id,{onDelete:'restrict'}), linkedBy: text('linked_by').notNull(), linkedAt: timestamp('linked_at',{withTimezone:true}).notNull().defaultNow() }, t=>[primaryKey({columns:[t.personId,t.clientId]}),uniqueIndex('platform_person_clients_client_unique').on(t.clientId),uniqueIndex('platform_person_clients_person_unique').on(t.personId),check('platform_person_clients_actor_check',sql`char_length(${t.linkedBy}) BETWEEN 1 AND 120`)]);
export const platformPersonStaff = pgTable('platform_person_staff', { personId: uuid('person_id').notNull().references(()=>platformPersons.id,{onDelete:'restrict'}), professionalId: uuid('professional_id').notNull().references(()=>staffProfessionals.id,{onDelete:'restrict'}), linkedBy: text('linked_by').notNull(), linkedAt: timestamp('linked_at',{withTimezone:true}).notNull().defaultNow() }, t=>[primaryKey({columns:[t.personId,t.professionalId]}),uniqueIndex('platform_person_staff_professional_unique').on(t.professionalId),uniqueIndex('platform_person_staff_person_unique').on(t.personId),check('platform_person_staff_actor_check',sql`char_length(${t.linkedBy}) BETWEEN 1 AND 120`)]);
export const trainingAccountLinks = pgTable('training_account_links', { linkId: uuid('link_id').defaultRandom().primaryKey(), requestId: uuid('request_id').notNull(), personId: uuid('person_id').notNull().references(()=>platformPersons.id,{onDelete:'restrict'}), trainingUserId: text('training_user_id').notNull(), status: text('status').notNull().default('active'), method: text('method').notNull(), sourceTransactionId: uuid('source_transaction_id'), sourceReceiptId: uuid('source_receipt_id'), linkVersion: integer('link_version').notNull().default(1), createdBy: text('created_by').notNull(), updatedBy: text('updated_by').notNull(), createdAt: timestamp('created_at',{withTimezone:true}).notNull().defaultNow(), updatedAt: timestamp('updated_at',{withTimezone:true}).notNull().defaultNow(), revokedAt: timestamp('revoked_at',{withTimezone:true}) }, t=>[uniqueIndex('training_account_links_request_id_key').on(t.requestId),uniqueIndex('training_account_links_one_nonterminal_person').on(t.personId).where(sql`${t.status} IN ('pending','active','revocation_pending')`),uniqueIndex('training_account_links_one_nonterminal_user').on(t.trainingUserId).where(sql`${t.status} IN ('pending','active','revocation_pending')`),uniqueIndex('training_account_links_source_receipt_key').on(t.sourceReceiptId).where(sql`${t.sourceReceiptId} IS NOT NULL`),uniqueIndex('training_account_links_source_transaction_key').on(t.sourceTransactionId).where(sql`${t.sourceTransactionId} IS NOT NULL`),check('training_account_links_status_check',sql`${t.status} IN ('pending','active','revocation_pending','revoked','conflict')`),check('training_account_links_method_check',sql`${t.method} IN ('explicit_admin','verified_training_proof')`),check('training_account_links_source_check',sql`(${t.method}='explicit_admin' AND ${t.sourceTransactionId} IS NULL AND ${t.sourceReceiptId} IS NULL AND ${t.status} IN ('active','revoked')) OR (${t.method}='verified_training_proof' AND ${t.sourceTransactionId} IS NOT NULL AND ${t.sourceReceiptId} IS NOT NULL)`),check('training_account_links_version_check',sql`${t.linkVersion}>0`),check('training_account_links_user_id_check',sql`${t.trainingUserId}=btrim(${t.trainingUserId}) AND char_length(btrim(${t.trainingUserId})) BETWEEN 1 AND 200`),check('training_account_links_revoked_check',sql`(${t.status}='revoked') = (${t.revokedAt} IS NOT NULL)`),check('training_account_links_actor_check',sql`char_length(${t.createdBy}) BETWEEN 1 AND 120 AND char_length(${t.updatedBy}) BETWEEN 1 AND 120`)]);
export const platformIdentityAuditEvents = pgTable('platform_identity_audit_events', { id: uuid('id').defaultRandom().primaryKey(), personId: uuid('person_id').notNull(), actorId: text('actor_id').notNull(), action: text('action').notNull(), resourceId: uuid('resource_id').notNull(), details: jsonb('details').notNull().default({}), occurredAt: timestamp('occurred_at',{withTimezone:true}).notNull().defaultNow() }, t=>[foreignKey({name:'platform_identity_audit_person_id_platform_persons_id_fk',columns:[t.personId],foreignColumns:[platformPersons.id]}).onDelete('restrict'),index('platform_identity_audit_person_timeline_idx').on(t.personId,t.occurredAt.desc(),t.id.desc()),check('platform_identity_audit_actor_check',sql`char_length(${t.actorId}) BETWEEN 1 AND 120`),check('platform_identity_audit_action_check',sql`${t.action} IN ('person.created','person.client_linked','person.staff_linked','training.linked','training.link_revoked','person.auth_subject_linked','person.auth_subject_revoked','training.link_transaction_created','training.link_transaction_verified','training.link_transaction_consumed','training.link_transaction_cancelled','training.link_transaction_expired')`),check('platform_identity_audit_details_check',sql`jsonb_typeof(${t.details})='object'`)]);
export const platformPersonAuthSubjects = pgTable('platform_person_auth_subjects',{id:uuid('id').defaultRandom().primaryKey(),personId:uuid('person_id').notNull().references(()=>platformPersons.id,{onDelete:'restrict'}),authSubject:text('auth_subject').notNull(),provider:text('provider').notNull(),providerVersion:smallint('provider_version').notNull().default(1),status:text('status').notNull().default('active'),verifiedAt:timestamp('verified_at',{withTimezone:true}).notNull().defaultNow(),createdAt:timestamp('created_at',{withTimezone:true}).notNull().defaultNow(),createdBy:text('created_by').notNull(),revokedAt:timestamp('revoked_at',{withTimezone:true}),revokedBy:text('revoked_by')},t=>[uniqueIndex('platform_person_auth_subject_owner_unique').on(t.provider,t.authSubject),index('platform_person_auth_subject_person_active_idx').on(t.personId,t.createdAt.desc()).where(sql`${t.status}='active'`),check('platform_person_auth_subject_canonical',sql`${t.authSubject}=btrim(${t.authSubject}) AND char_length(${t.authSubject}) BETWEEN 1 AND 500 AND ${t.authSubject} !~ '[[:cntrl:]]'`),check('platform_person_auth_provider_check',sql`${t.provider}=btrim(${t.provider}) AND ${t.provider} ~ '^[a-z][a-z0-9.-]{0,63}$'`),check('platform_person_auth_provider_version_check',sql`${t.providerVersion} BETWEEN 1 AND 32767`),check('platform_person_auth_status_check',sql`${t.status} IN ('active','revoked')`),check('platform_person_auth_revocation_check',sql`(${t.status}='active' AND ${t.revokedAt} IS NULL AND ${t.revokedBy} IS NULL) OR (${t.status}='revoked' AND ${t.revokedAt} IS NOT NULL AND ${t.revokedBy} IS NOT NULL)`),check('platform_person_auth_actor_check',sql`char_length(${t.createdBy}) BETWEEN 1 AND 120 AND (${t.revokedBy} IS NULL OR char_length(${t.revokedBy}) BETWEEN 1 AND 120)`)]);
export const trainingLinkTransactions = pgTable('training_link_transactions', {
  transactionId: uuid('transaction_id').defaultRandom().primaryKey(),
  personId: uuid('person_id').notNull().references(() => platformPersons.id, { onDelete: 'restrict' }),
  authSubjectLinkId: uuid('auth_subject_link_id').notNull().references(() => platformPersonAuthSubjects.id, { onDelete: 'restrict' }),
  requestId: uuid('request_id').notNull(),
  requestHash: char('request_hash', { length: 64 }).notNull(),
  state: text('state').notNull().default('pending'),
  nonceHash: char('nonce_hash', { length: 64 }).notNull(),
  verifiedTrainingUserId: text('verified_training_user_id'),
  audience: text('audience').notNull(),
  purpose: text('purpose').notNull(),
  expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  verifiedAt: timestamp('verified_at', { withTimezone: true }),
  sourceReceiptId: uuid('source_receipt_id'),
  consumedAt: timestamp('consumed_at', { withTimezone: true }),
  cancelledAt: timestamp('cancelled_at', { withTimezone: true }),
  failureReason: text('failure_reason'),
  version: integer('version').notNull().default(1),
}, (t) => [
  uniqueIndex('training_link_transactions_request_id_key').on(t.requestId),
  uniqueIndex('training_link_transactions_nonce_hash_key').on(t.nonceHash),
  uniqueIndex('training_link_transactions_source_receipt_key').on(t.sourceReceiptId),
  index('training_link_transactions_person_state_idx').on(t.personId, t.state, t.expiresAt),
  check('training_link_transactions_state_check', sql`${t.state} IN ('pending','verified','consumed','expired','cancelled')`),
  check('training_link_transactions_hash_check', sql`${t.requestHash} ~ '^[0-9a-f]{64}$' AND ${t.nonceHash} ~ '^[0-9a-f]{64}$'`),
  check('training_link_tx_verified_subject_canonical_check', sql`${t.verifiedTrainingUserId} IS NULL OR (${t.verifiedTrainingUserId}=btrim(${t.verifiedTrainingUserId}) AND char_length(${t.verifiedTrainingUserId}) BETWEEN 1 AND 200 AND ${t.verifiedTrainingUserId} !~ '[[:cntrl:]]')`),
  check('training_link_tx_verified_subject_state_check', sql`(${t.state}='pending' AND ${t.verifiedTrainingUserId} IS NULL) OR (${t.state} IN ('verified','consumed') AND ${t.verifiedTrainingUserId} IS NOT NULL) OR ${t.state} IN ('expired','cancelled')`),
  check('training_link_transactions_audience_check', sql`${t.audience}='2j-training-account-link'`),
  check('training_link_transactions_purpose_check', sql`${t.purpose}='training-account-link'`),
  check('training_link_transactions_ttl_check', sql`${t.expiresAt}>${t.createdAt} AND ${t.expiresAt}<=${t.createdAt}+interval '5 minutes'`),
  check('training_link_transactions_state_timestamps_check', sql`(${t.state}='pending' AND ${t.verifiedAt} IS NULL AND ${t.consumedAt} IS NULL AND ${t.cancelledAt} IS NULL) OR (${t.state}='verified' AND ${t.verifiedAt} IS NOT NULL AND ${t.consumedAt} IS NULL AND ${t.cancelledAt} IS NULL) OR (${t.state}='consumed' AND ${t.verifiedAt} IS NOT NULL AND ${t.consumedAt} IS NOT NULL AND ${t.cancelledAt} IS NULL) OR (${t.state}='expired' AND ${t.consumedAt} IS NULL AND ${t.cancelledAt} IS NULL) OR (${t.state}='cancelled' AND ${t.consumedAt} IS NULL AND ${t.cancelledAt} IS NOT NULL)`),
  check('training_link_transactions_failure_check', sql`${t.failureReason} IS NULL OR (${t.state} IN ('expired','cancelled') AND char_length(${t.failureReason}) BETWEEN 1 AND 80)`),
  check('training_link_transactions_version_check', sql`${t.version}>0`),
  check('training_link_transactions_receipt_state_check', sql`${t.sourceReceiptId} IS NULL OR ${t.state} IN ('verified','consumed','expired')`),
]);
